SELECT COUNT(DISTINCT analytics_order_facts.active_customer_id) AS active_customer_count FROM analytics_order_facts WHERE analytics_order_facts.year = 2022 AND analytics_order_facts.month = 8 AND analytics_order_facts.region = 'South' AND analytics_order_facts.channel = 'marketplace' AND analytics_order_facts.customer_segment = 'enterprise' AND analytics_order_facts.payment_method = 'voucher' LIMIT 1000
